import { randomUUID } from 'node:crypto';

// Issuing a token takes the Carrier half a second. It honours one for ten seconds, and for a
// second of grace after that, so a caller that keeps it to the last moment is not caught out
// by the time its request spends on the way here
const ISSUE_MS = 500;
const LIFETIME_S = 10;
const GRACE_MS = 1000;

// No more than two tokens in any ten seconds
const LIMIT = 2;
const WINDOW_MS = 10_000;

// When each token it has issued stops being honoured
const expiries = new Map();
let issuedAt = [];
let issued = 0;
const quoted = new Set();

export const metrics = { 'tokens refused': 'Count' };

async function token(metric) {
  const now = Date.now();
  issuedAt = issuedAt.filter((at) => now - at < WINDOW_MS);
  if (issuedAt.length >= LIMIT) {
    metric('tokens refused', 1);
    console.log('refused a token: two were issued in the last ten seconds');
    const retryAfter = Math.ceil((issuedAt[0] + WINDOW_MS - now) / 1000);
    return Response.json(
      { error: 'Too many tokens requested' },
      { status: 429, headers: { 'retry-after': String(retryAfter) } }
    );
  }
  issuedAt.push(now);
  await new Promise((resolve) => setTimeout(resolve, ISSUE_MS));

  const value = randomUUID();
  expiries.set(value, Date.now() + LIFETIME_S * 1000 + GRACE_MS);
  issued += 1;
  metric('tokens issued', issued, 'None');
  console.log(`issued token ${issued}`);
  return Response.json({ access_token: value, token_type: 'Bearer', expires_in: LIFETIME_S });
}

function rate(request, parcel, metric) {
  const [scheme, value] = (request.headers.get('authorization') ?? '').split(' ');
  const expires = scheme === 'Bearer' ? expiries.get(value) : undefined;
  if (expires === undefined) {
    return Response.json({ error: 'Missing or unknown access token' }, { status: 401 });
  }
  if (Date.now() > expires) {
    return Response.json({ error: 'The access token has expired' }, { status: 401 });
  }
  if (!parcel) {
    return Response.json({ error: 'Name the parcel, as in /rates?parcel=7' }, { status: 400 });
  }
  quoted.add(parcel);
  metric('parcels quoted', quoted.size, 'None');
  return Response.json({ parcel, rate: 500 + (Number(parcel) % 7) * 150 });
}

export async function handle(request, { metric }) {
  const { pathname, searchParams } = new URL(request.url);
  if (request.method === 'POST' && pathname === '/token') return token(metric);
  if (request.method === 'GET' && pathname === '/rates') {
    return rate(request, searchParams.get('parcel'), metric);
  }
  return new Response('Not found\n', { status: 404 });
}

